import { useState, useEffect, memo } from 'react';
import { useParams } from 'react-router-dom';
import { getDetail } from '../lib/tmdb';
import StreamPlayerInner from '../components/StreamPlayer';

// Watch page wrapper - extracts params from route and passes them to StreamPlayerInner
function WatchPage() {
  const params = useParams<{ type: string; id: string; season?: string; episode?: string }>();
  
  const tmdbId = parseInt(params.id || '0', 10);
  const type = (params.type === 'movie' || params.type === 'tv') ? params.type : 'movie';
  const season = params.season ? parseInt(params.season, 10) : undefined;
  const episode = params.episode ? parseInt(params.episode, 10) : undefined;
  
  const [title, setTitle] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadTitle = async () => {
      try {
        const detail = await getDetail(type, tmdbId);
        if (detail) {
          setTitle(type === 'movie' ? (detail.title || 'Unknown') : (detail.name || 'Unknown'));
        } else {
          setTitle('Unknown Title');
        }
      } catch {
        setTitle('Unknown Title');
      } finally {
        setLoading(false);
      }
    };
    loadTitle();
  }, [tmdbId, type]);

  if (loading || !title) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-black">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="mt-4 text-white/60">Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <StreamPlayerInner
      tmdbId={tmdbId}
      type={type}
      title={title}
      season={season}
      episode={episode}
    />
  );
}

export default memo(WatchPage);
