import { useState, useRef, useEffect, useCallback, memo, useMemo } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import {
  Play, Pause, Maximize, Minimize, Volume2, VolumeX,
  Settings, SkipForward, RotateCcw, Film, ChevronDown,
  Circle, Monitor, Rewind, Heart, Share2, Copy, X,
  List, Keyboard, FastForward, Flag, Info, Home,
  ChevronLeft, ChevronRight, Volume1, MonitorCheck
} from 'lucide-react';
import { useSettings } from '../contexts/SettingsContext';
import { useToast } from '../contexts/ToastContext';
import { useHistory } from '../contexts/HistoryContext';
import { getImdbId, getVideos } from '../lib/tmdb';
import { getStreamLinksForItem, generateDirectStreamLinks, generateMovieEmbedSources, generateTVEmbedSources } from '../lib/streamSources';
import type { StreamLink } from '../lib/streamSources';

interface StreamPlayerProps {
  tmdbId: number;
  type: 'movie' | 'tv';
  title: string;
  season?: number;
  episode?: number;
  backdropUrl?: string;
  posterUrl?: string;
  overview?: string;
  releaseDate?: string;
  voteAverage?: number;
  genres?: Array<{ id: number; name: string }>;
  cast?: Array<{ id: number; name: string; character: string }>;
  crew?: Array<{ id: number; name: string; job: string }>;
  episodes?: Array<{
    season: number;
    episode: number;
    name: string;
    overview: string;
    still_path: string | null;
    vote_average: number;
    air_date: string;
  }>;
}

const SPEED_OPTIONS = [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2];
const AUTO_ADVANCE_DELAY = 5000;

function StreamPlayerInner({
  tmdbId, type, title, season, episode,
  backdropUrl, posterUrl, overview, releaseDate, voteAverage, genres, cast, crew, episodes
}: StreamPlayerProps) {
  const navigate = useNavigate();
  const { settings, updateSetting } = useSettings();
  const { addToast } = useToast();
  const { addToHistory, getRecentViews } = useHistory();
  const params = useParams();

  const [streams, setStreams] = useState<StreamLink[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentStream, setCurrentStream] = useState(0);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [showSourceSelector, setShowSourceSelector] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [isPlaying, setIsPlaying] = useState(true);
  const [volume, setVolume] = useState(1);
  const [muted, setMuted] = useState(false);
  const [playbackSpeed, setPlaybackSpeed] = useState(settings.playbackSpeed);
  const [isTheater, setIsTheater] = useState(false);
  const [isCinema, setIsCinema] = useState(false);
  const [inWatchlist, setInWatchlist] = useState(false);
  const [iframeKey, setIframeKey] = useState(0);
  const [isPiP, setIsPiP] = useState(false);
  const [showInfo, setShowInfo] = useState(false);

  const iframeRef = useRef<HTMLIFrameElement>(null);
  const controlsTimeout = useRef<ReturnType<typeof setTimeout>>();
  const playerContainerRef = useRef<HTMLDivElement>(null);
  const hideSettingsTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const s = season || 1;
  const e = episode || 1;

  // Load watchlist state
  const watchlist = useMemo(() => {
    try {
      const stored = localStorage.getItem('watchlist-ids');
      return stored ? JSON.parse(stored) : [];
    } catch { return []; }
  }, []);

  // Load streams
  useEffect(() => {
    const loadStreams = async () => {
      try {
        const imdbId = await getImdbId(type, tmdbId);
        const idParam = imdbId || String(tmdbId);
        let loadedStreams: StreamLink[] = [];

        if (type === 'movie') {
          loadedStreams = [
            ...generateMovieEmbedSources(idParam, tmdbId),
            ...generateDirectStreamLinks(idParam, tmdbId, 'movie'),
          ];
        } else {
          loadedStreams = [
            ...generateTVEmbedSources(idParam, tmdbId, s, e),
            ...generateDirectStreamLinks(idParam, tmdbId, 'tv', s, e),
          ];
        }

        setStreams(loadedStreams);

        const defaultIdx = loadedStreams.findIndex(
          src => src.name.toLowerCase().includes(settings.defaultStreamSource.toLowerCase())
        );
        setCurrentStream(defaultIdx >= 0 ? defaultIdx : 0);

        addToHistory({
          id: tmdbId,
          type,
          title,
          poster_path: posterUrl || null,
          episode: e,
          season: s,
        });
      } catch (error) {
        console.error('Error loading streams:', error);
      } finally {
        setLoading(false);
      }
    };

    loadStreams();
    setInWatchlist(watchlist.includes(tmdbId));
  }, [tmdbId, type, s, e, settings.defaultStreamSource]);

  // Fullscreen handling
  const toggleFullscreen = useCallback(() => {
    if (!document.fullscreenElement && playerContainerRef.current) {
      playerContainerRef.current.requestFullscreen().catch(() => {});
    } else {
      document.exitFullscreen().catch(() => {});
    }
  }, []);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  // Controls auto-hide
  const handleMouseMove = useCallback(() => {
    setShowControls(true);
    clearTimeout(controlsTimeout.current);
    if (isPlaying) {
      controlsTimeout.current = setTimeout(() => {
        setShowControls(false);
      }, 3000);
    }
  }, [isPlaying]);

  // Click to toggle play/pause
  const handlePlayerClick = useCallback(() => {
    setIsPlaying(prev => !prev);
  }, []);

  // Double click for fullscreen
  const handleDoubleClick = useCallback(() => {
    toggleFullscreen();
  }, [toggleFullscreen]);

  const togglePlay = useCallback(() => setIsPlaying(prev => !prev), []);
  const toggleMute = useCallback(() => setMuted(prev => !prev), []);

  const changeVolume = useCallback((newVolume: number) => {
    setVolume(newVolume);
    if (newVolume > 0) setMuted(false);
  }, []);

  const changeSpeed = useCallback((speed: number) => {
    setPlaybackSpeed(speed);
    updateSetting('playbackSpeed', speed);
    setShowSettings(false);
    addToast(`Playback speed: ${speed}x`, 'info');
  }, [updateSetting, addToast]);

  const addWatchlist = useCallback(() => {
    const newWatchlist = inWatchlist
      ? watchlist.filter((id: number) => id !== tmdbId)
      : [...watchlist, tmdbId];
    setInWatchlist(!inWatchlist);
    localStorage.setItem('watchlist-ids', JSON.stringify(newWatchlist));
    addToast(
      inWatchlist ? 'Removed from watchlist' : 'Added to watchlist',
      inWatchlist ? 'info' : 'success'
    );
  }, [inWatchlist, tmdbId, watchlist, addToast]);

  const shareContent = useCallback(() => {
    const url = `${window.location.origin}/watch/${type}/${tmdbId}`;
    navigator.clipboard.writeText(url).then(() => {
      addToast('Link copied to clipboard!', 'copy');
    }).catch(() => {
      addToast('Failed to copy link', 'error');
    });
  }, [tmdbId, type, addToast]);

  const copyEmbedCode = useCallback(() => {
    const stream = streams[currentStream];
    if (!stream) return;
    const embedCode = `<iframe src="${stream.url}" frameborder="0" allowfullscreen width="100%" height="500"></iframe>`;
    navigator.clipboard.writeText(embedCode).then(() => {
      addToast('Embed code copied!', 'copy');
    }).catch(() => {
      addToast('Failed to copy embed code', 'error');
    });
  }, [streams, currentStream, addToast]);

  const goNextEpisode = useCallback(() => {
    if (type === 'tv' && episodes) {
      const currentEpIndex = episodes.findIndex(ep => ep.season === s && ep.episode === e);
      const nextEpIndex = currentEpIndex + 1;
      if (nextEpIndex >= 0 && nextEpIndex < episodes.length) {
        const nextEp = episodes[nextEpIndex];
        navigate(`/watch/tv/${tmdbId}/${nextEp.season}/${nextEp.episode}`);
      }
    }
  }, [type, episodes, s, e, tmdbId, navigate]);

  const goPrevEpisode = useCallback(() => {
    if (type === 'tv' && episodes) {
      const currentEpIndex = episodes.findIndex(ep => ep.season === s && ep.episode === e);
      const prevEpIndex = currentEpIndex - 1;
      if (prevEpIndex >= 0) {
        const prevEp = episodes[prevEpIndex];
        navigate(`/watch/tv/${tmdbId}/${prevEp.season}/${prevEp.episode}`);
      }
    }
  }, [type, episodes, s, e, tmdbId, navigate]);

  const selectSource = useCallback((index: number) => {
    setCurrentStream(index);
    setShowSourceSelector(false);
    setIframeKey(k => k + 1);
    addToast(`Switched to ${streams[index]?.name}`, 'info');
  }, [streams, addToast]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      
      switch (e.key) {
        case ' ':
        case 'k':
          e.preventDefault();
          togglePlay();
          break;
        case 'f':
          e.preventDefault();
          toggleFullscreen();
          break;
        case 'm':
          e.preventDefault();
          toggleMute();
          break;
        case 'ArrowRight':
          e.preventDefault();
          addToast('Fast forward 10s (not available for embed players)', 'info');
          break;
        case 'ArrowLeft':
          e.preventDefault();
          addToast('Rewind 10s (not available for embed players)', 'info');
          break;
        case 'Escape':
          if (isTheater || isCinema) {
            setIsTheater(false);
            setIsCinema(false);
          }
          break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [togglePlay, toggleFullscreen, toggleMute, isTheater, isCinema]);

  // Cleanup
  useEffect(() => {
    return () => {
      clearTimeout(controlsTimeout.current);
      if (hideSettingsTimer.current) clearTimeout(hideSettingsTimer.current);
    };
  }, []);

  const currentStreamData = streams[currentStream];

  const containerClass = isTheater
    ? 'fixed inset-0 z-[9999] bg-black flex items-center justify-center'
    : isCinema
    ? 'fixed inset-0 z-[9999] bg-black/95 flex items-center justify-center'
    : 'relative w-full h-full';

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full bg-black min-h-[60vh]">
        <div className="text-center space-y-4">
          <div className="w-16 h-16 border-4 border-emerald-400 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-white/60 animate-pulse">Loading streams...</p>
        </div>
      </div>
    );
  }

  return (
    <div className={containerClass}>
      <div
        ref={playerContainerRef}
        className={`relative w-full ${isTheater || isCinema ? 'h-full max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto' : ''} bg-black`}
        onMouseMove={handleMouseMove}
        onMouseLeave={() => setShowControls(false)}
      >
        {/* Player */}
        <div className={`w-full ${isTheater || isCinema ? 'h-full' : 'aspect-video'} relative group`}>
          {currentStreamData ? (
            <iframe
              key={iframeKey}
              ref={iframeRef}
              src={currentStreamData.url}
              className="w-full h-full border-0"
              allow="autoplay; encrypted-media; picture-in-picture; fullscreen"
              allowFullScreen
              sandbox="allow-same-origin allow-scripts allow-popups allow-forms allow-modals"
              loading="lazy"
            />
          ) : (
            <div className="w-full h-full flex flex-col items-center justify-center text-white/40 gap-4 bg-gradient-to-br from-black to-gray-900">
              <p className="text-lg font-medium">No streams available</p>
              <button
                onClick={() => navigate(-1)}
                className="px-4 py-2 bg-emerald-500 hover:bg-emerald-400 text-white rounded-lg transition-colors"
              >
                Go Back
              </button>
            </div>
          )}

          {/* Controls Overlay */}
          <div
            className={`absolute inset-0 transition-opacity duration-300 ${
              showControls || !isPlaying ? 'opacity-100' : 'opacity-0'
            }`}
          >
            {/* Top gradient */}
            <div className="absolute top-0 left-0 right-0 p-4 bg-gradient-to-b from-black/80 to-transparent">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <button
                    onClick={() => navigate(-1)}
                    className="p-2 text-white/80 hover:text-white bg-white/10 hover:bg-white/20 rounded-lg transition-all backdrop-blur-sm"
                    aria-label="Go back"
                  >
                    <ChevronLeft size={20} />
                  </button>
                  <div>
                    <h2 className="text-white font-semibold text-lg drop-shadow-lg">{title}</h2>
                    {type === 'tv' && (
                      <p className="text-white/60 text-sm">Season {s} · Episode {e}</p>
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <button
                    onClick={shareContent}
                    className="p-2 text-white/80 hover:text-white bg-white/10 hover:bg-white/20 rounded-lg transition-all backdrop-blur-sm"
                    aria-label="Share"
                  >
                    <Share2 size={18} />
                  </button>
                </div>
              </div>
            </div>

            {/* Center play/pause indicator */}
            {!isPlaying && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="w-16 h-16 rounded-full bg-black/50 backdrop-blur-sm flex items-center justify-center animate-fade-in">
                  <Play size={28} className="text-white ml-1" fill="white" />
                </div>
              </div>
            )}

            {/* Bottom controls */}
            <div className="absolute bottom-0 left-0 right-0 p-3 sm:p-4 bg-gradient-to-t from-black/80 via-black/40 to-transparent">
              {/* Progress bar (visual only for embeds) */}
              <div className="w-full h-1 bg-white/20 rounded-full mb-3 cursor-pointer group hover:h-2 transition-all">
                <div className="w-0 h-full bg-emerald-400 rounded-full group-hover:bg-emerald-300 relative transition-all" />
              </div>

              <div className="flex items-center justify-between gap-2">
                {/* Left controls */}
                <div className="flex items-center gap-1 sm:gap-2">
                  <button
                    onClick={togglePlay}
                    className="p-1.5 sm:p-2 text-white hover:text-emerald-400 transition-all"
                    aria-label={isPlaying ? 'Pause' : 'Play'}
                  >
                    {isPlaying ? <Pause size={22} /> : <Play size={22} />}
                  </button>

                  {type === 'tv' && (
                    <>
                      <button
                        onClick={goPrevEpisode}
                        className="p-1.5 sm:p-2 text-white/80 hover:text-white transition-all hidden sm:flex"
                        aria-label="Previous episode"
                      >
                        <RotateCcw size={18} />
                      </button>
                      <button
                        onClick={goNextEpisode}
                        className="p-1.5 sm:p-2 text-white/80 hover:text-white transition-all hidden sm:flex"
                        aria-label="Next episode"
                      >
                        <SkipForward size={18} />
                      </button>
                    </>
                  )}

                  {/* Volume */}
                  <div className="flex items-center gap-1 group/vol">
                    <button
                      onClick={toggleMute}
                      className="p-1.5 sm:p-2 text-white/80 hover:text-white transition-all"
                      aria-label={muted ? 'Unmute' : 'Mute'}
                    >
                      {muted || volume === 0 ? (
                        <VolumeX size={20} />
                      ) : volume < 0.5 ? (
                        <Volume1 size={20} />
                      ) : (
                        <Volume2 size={20} />
                      )}
                    </button>
                    <input
                      type="range"
                      min="0"
                      max="1"
                      step="0.05"
                      value={muted ? 0 : volume}
                      onChange={e => changeVolume(parseFloat(e.target.value))}
                      className="w-0 group-hover/vol:w-20 accent-emerald-400 transition-all duration-300 opacity-0 group-hover/vol:opacity-100"
                      aria-label="Volume"
                    />
                  </div>

                  {/* Source selector */}
                  {streams.length > 1 && (
                    <div className="relative">
                      <button
                        onClick={() => {
                          setShowSourceSelector(!showSourceSelector);
                          setShowSettings(false);
                        }}
                        className="flex items-center gap-1.5 px-2 sm:px-3 py-1.5 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all text-xs sm:text-sm backdrop-blur-sm"
                      >
                        <span className="hidden sm:inline truncate">{currentStreamData?.name}</span>
                        <span className="sm:hidden">Sources</span>
                        <ChevronDown size={14} />
                      </button>

                      {showSourceSelector && (
                        <div 
                          className="absolute bottom-full mb-2 left-0 w-64 max-h-80 bg-[#1a1a2e]/95 backdrop-blur-xl border border-white/10 rounded-xl shadow-2xl overflow-y-auto z-50"
                          onMouseEnter={() => {
                            if (hideSettingsTimer.current) clearTimeout(hideSettingsTimer.current);
                          }}
                          onMouseLeave={() => {
                            hideSettingsTimer.current = setTimeout(() => setShowSourceSelector(false), 500);
                          }}
                        >
                          <div className="p-2">
                            <p className="text-white/40 text-[10px] px-2 py-1 font-semibold uppercase tracking-wider">Sources</p>
                            {streams.map((stream, idx) => {
                              const reliabilityColor = stream.reliability === 'high'
                                ? 'bg-emerald-400'
                                : stream.reliability === 'medium'
                                  ? 'bg-amber-400'
                                  : 'bg-red-400';
                              
                              return (
                                <button
                                  key={idx}
                                  onClick={() => selectSource(idx)}
                                  className={`w-full text-left px-3 py-2 rounded-lg text-sm transition-all ${
                                    idx === currentStream
                                      ? 'bg-emerald-500/20 text-emerald-400 font-medium'
                                      : 'text-white/70 hover:bg-white/10 hover:text-white'
                                  }`}
                                >
                                  <div className="flex items-center justify-between gap-2">
                                    <div className="flex items-center gap-2 min-w-0">
                                      <div className={`w-2 h-2 rounded-full flex-shrink-0 ${reliabilityColor}`} title={`Reliability: ${stream.reliability || 'unknown'}`} />
                                      <span className="truncate">{stream.name}</span>
                                    </div>
                                    <div className="flex items-center gap-2 flex-shrink-0">
                                      <span className="text-[10px] px-1.5 py-0.5 rounded bg-white/10 text-white/50">{stream.quality}</span>
                                      {idx === currentStream && (
                                        <div className="w-2 h-2 rounded-full bg-emerald-400" />
                                      )}
                                    </div>
                                  </div>
                                </button>
                              );
                            })}
                          </div>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {/* Right controls */}
                <div className="flex items-center gap-1 sm:gap-2">
                  {/* Settings */}
                  <div className="relative">
                    <button
                      onClick={() => {
                        setShowSettings(!showSettings);
                        setShowSourceSelector(false);
                      }}
                      className={`p-1.5 sm:p-2 transition-all ${showSettings ? 'text-emerald-400' : 'text-white/80 hover:text-white'}`}
                      aria-label="Settings"
                    >
                      <Settings size={20} />
                    </button>

                    {showSettings && (
                      <div 
                        className="absolute bottom-full mb-2 right-0 w-52 bg-[#1a1a2e]/95 backdrop-blur-xl border border-white/10 rounded-xl shadow-2xl p-3 z-50"
                        onMouseEnter={() => {
                          if (hideSettingsTimer.current) clearTimeout(hideSettingsTimer.current);
                        }}
                        onMouseLeave={() => {
                          hideSettingsTimer.current = setTimeout(() => setShowSettings(false), 500);
                        }}
                      >
                        <p className="text-white/40 text-[10px] mb-2 font-semibold uppercase tracking-wider">Speed</p>
                        <div className="grid grid-cols-4 gap-1">
                          {SPEED_OPTIONS.map(speed => (
                            <button
                              key={speed}
                              onClick={() => changeSpeed(speed)}
                              className={`px-2 py-1.5 rounded text-xs font-medium transition-all ${
                                playbackSpeed === speed
                                  ? 'bg-emerald-500 text-white shadow-lg'
                                  : 'bg-white/5 text-white/60 hover:bg-white/15 hover:text-white'
                              }`}
                            >
                              {speed}x
                            </button>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Theater mode */}
                  <button
                    onClick={() => { setIsTheater(!isTheater); setIsCinema(false); }}
                    className={`p-1.5 sm:p-2 transition-all hidden sm:flex ${isTheater ? 'text-emerald-400' : 'text-white/80 hover:text-white'}`}
                    aria-label="Theater mode"
                  >
                    <Monitor size={20} />
                  </button>

                  {/* Cinema mode */}
                  <button
                    onClick={() => { setIsCinema(!isCinema); setIsTheater(false); }}
                    className={`p-1.5 sm:p-2 transition-all hidden sm:flex ${isCinema ? 'text-emerald-400' : 'text-white/80 hover:text-white'}`}
                    aria-label="Cinema mode"
                  >
                    <Film size={20} />
                  </button>

                  {/* Fullscreen */}
                  <button
                    onClick={toggleFullscreen}
                    className="p-1.5 sm:p-2 text-white/80 hover:text-white transition-all"
                    aria-label={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
                  >
                    {isFullscreen ? <Minimize size={20} /> : <Maximize size={20} />}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Info Panel */}
      {showInfo && (
        <div className="fixed inset-0 z-[9998] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4" onClick={() => setShowInfo(false)}>
          <div className="bg-[#1a1a2e] rounded-2xl max-w-2xl w-full max-h-[80vh] overflow-y-auto border border-white/10" onClick={e => e.stopPropagation()}>
            <div className="relative h-48">
              {backdropUrl && (
                <img src={backdropUrl} alt="" className="w-full h-full object-cover rounded-t-2xl" loading="lazy" />
              )}
              <div className="absolute inset-0 bg-gradient-to-t from-[#1a1a2e] to-transparent" />
              <button
                onClick={() => setShowInfo(false)}
                className="absolute top-4 right-4 p-2 bg-black/50 hover:bg-black/70 text-white rounded-full transition-all"
              >
                <X size={20} />
              </button>
            </div>
            <div className="p-6 space-y-4">
              <div>
                <h2 className="text-2xl font-bold text-white">{title}</h2>
                <div className="flex items-center gap-3 mt-2">
                  {voteAverage && (
                    <span className="flex items-center gap-1 text-amber-400">
                      <span className="font-semibold">{voteAverage.toFixed(1)}</span>
                      <span className="text-white/40 text-sm">/10</span>
                    </span>
                  )}
                  {releaseDate && (
                    <span className="text-white/50 text-sm">{releaseDate.slice(0, 4)}</span>
                  )}
                </div>
              </div>
              {overview && (
                <p className="text-white/70 text-sm leading-relaxed">{overview}</p>
              )}
              <div className="flex flex-wrap gap-2">
                <button
                  onClick={addWatchlist}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all ${
                    inWatchlist
                      ? 'bg-emerald-500 text-white'
                      : 'bg-white/10 text-white hover:bg-white/20'
                  }`}
                >
                  <Heart size={16} fill={inWatchlist ? 'white' : 'none'} />
                  {inWatchlist ? 'In Watchlist' : 'Add to Watchlist'}
                </button>
                <button
                  onClick={shareContent}
                  className="flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all"
                >
                  <Share2 size={16} />
                  Share
                </button>
                <button
                  onClick={copyEmbedCode}
                  className="flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all"
                >
                  <Copy size={16} />
                  Copy Embed
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default memo(StreamPlayerInner);